import {
  Component,
  ChangeDetectionStrategy,
  signal,
} from '@angular/core';
import { CommonModule, Location } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { NotificationService } from '../../../../shared/services/notification.service';

@Component({
  selector: 'app-one-on-one-edit-page',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    MatIconModule,
    MatButtonModule,
  ],
  templateUrl: './one-on-one-edit-page.component.html',
  styleUrl: './one-on-one-edit-page.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class OneOnOneEditPageComponent {
  // Mock current event data
  eventInfo = {
    eventName: 'テスト',
    organizer: '秀次郎',
    duration: '60分',
    deadline: '2026年4月16日(木) 17:30',
  };

  editForm: FormGroup;
  changeCandidateConditions = signal(false);

  mtgTools = [
    'オンラインMTGでは行わない',
    'Zoom',
    'Google Meet',
    'Microsoft Teams',
  ];

  constructor(private fb: FormBuilder, private location: Location, private notification: NotificationService) {
    this.editForm = this.fb.group({
      eventName: ['テスト'],
      isPrivate: [false],
      startChat: [true],
      registerSalesforce: [false],
      mtgTool: ['Zoom'],
      location: ['オンライン'],
      description: ['次回の1on1では、Q2の目標進捗について確認します。'],
    });
  }

  onFileDropped(event: DragEvent): void {
    event.preventDefault();
  }

  onDragOver(event: DragEvent): void {
    event.preventDefault();
  }

  onSubmit(): void {
    console.log('Form submitted:', this.editForm.value);
    this.notification.success('予定調整を更新しました');
  }

  goBack(): void {
    this.location.back();
  }
}
